package com.ruoyi.paiflow.service;

import com.alibaba.fastjson2.*;
import com.networknt.schema.*;
import java.util.*;
import static com.ruoyi.paiflow.service.ModelOperationJson.error;

/** 原Link使用Draft7；引用限同一已固定文档，无外部Schema/DNS/文件读取。 */
final class ToolJsonSchema {
 private static final JsonSchemaFactory FACTORY=JsonSchemaFactory.getInstance(SpecVersion.VersionFlag.V7,
     b->b.schemaLoaders(l->l.add(iri->{throw new IllegalArgumentException("外部工具Schema不可读取");})));
 private ToolJsonSchema(){}
 static Object pointer(JSONObject root,String reference){
  if(reference==null||!reference.startsWith("#/"))throw error("工具Schema引用必须属于固定文档",422);
  Object value=root;for(String key:reference.substring(2).split("/",-1)){key=key.replace("~1","/").replace("~0","~");if(value instanceof JSONObject o)value=o.get(key);else if(value instanceof JSONArray a)try{value=a.get(Integer.parseInt(key));}catch(RuntimeException e){value=null;}else value=null;if(value==null)throw error("工具Schema引用不存在",422);}return value;
 }
 static JSONObject dereference(JSONObject root,JSONObject raw){var seen=new HashSet<String>();while(raw.containsKey("$ref")){String ref=raw.getString("$ref");if(!seen.add(ref)||!(pointer(root,ref) instanceof JSONObject o))throw error("工具OpenAPI结构引用循环/形状错误",422);raw=o;}return raw;}
 private static final Set<String> NAME_MAPS=Set.of("properties","patternProperties","definitions","$defs","schemas","requestBodies","responses","parameters","securitySchemes","paths");
 private static void refs(Object raw,JSONObject root,int depth){refs(raw,root,depth,false);}
 private static void refs(Object raw,JSONObject root,int depth,boolean names){if(depth>64)throw error("工具Schema过深",422);if(raw instanceof JSONObject o){if(!names){if(o.containsKey("$ref"))pointer(root,o.getString("$ref"));if(o.containsKey("$schema")&&!Set.of("http://json-schema.org/draft-07/schema#","https://json-schema.org/draft-07/schema").contains(o.getString("$schema")))throw error("原Link仅Draft7 Schema",422);}for(var field:o.entrySet())if(names||!Set.of("default","const","enum","examples").contains(field.getKey()))refs(field.getValue(),root,depth+1,!names&&NAME_MAPS.contains(field.getKey()));}else if(raw instanceof JSONArray a)for(Object v:a)refs(v,root,depth+1,false);}
 private static void stripIdentifiers(Object raw){stripIdentifiers(raw,false);}
 private static void stripIdentifiers(Object raw,boolean names){if(raw instanceof JSONObject o){if(!names){o.remove("$id");o.remove("$schema");}for(var field:o.entrySet())if(names||!Set.of("default","const","enum","examples").contains(field.getKey()))stripIdentifiers(field.getValue(),!names&&NAME_MAPS.contains(field.getKey()));}else if(raw instanceof JSONArray a)for(Object v:a)stripIdentifiers(v,false);}
 static JSONObject bundled(JSONObject raw,JSONObject api){var s=JSON.parseObject(raw.toJSONString(JSONWriter.Feature.WriteMapNullValue));if(api!=null){if(api.get("components") instanceof JSONObject c)s.put("components",JSON.parseObject(c.toJSONString(JSONWriter.Feature.WriteMapNullValue)));if(api.get("paths") instanceof JSONObject p)s.put("paths",JSON.parseObject(p.toJSONString(JSONWriter.Feature.WriteMapNullValue)));}refs(s,s,0);stripIdentifiers(s);return s;}
 static void check(JSONObject raw,JSONObject api){if(raw==null)throw error("工具Schema缺失",422);try{var schema=FACTORY.getSchema(bundled(raw,api).toJSONString(JSONWriter.Feature.WriteMapNullValue),InputFormat.JSON,SchemaValidatorsConfig.builder().formatAssertionsEnabled(false).build());schema.initializeValidators();}catch(com.ruoyi.common.exception.ServiceException e){throw e;}catch(RuntimeException e){throw error("工具Draft7 Schema或引用无效",422);}}
 static void validate(Object value,JSONObject raw,JSONObject api,String path){try{var schema=FACTORY.getSchema(bundled(raw,api).toJSONString(JSONWriter.Feature.WriteMapNullValue),InputFormat.JSON,SchemaValidatorsConfig.builder().formatAssertionsEnabled(false).build());if(!schema.validate(JSON.toJSONString(value,JSONWriter.Feature.WriteMapNullValue),InputFormat.JSON).isEmpty())throw error("工具Draft7参数/响应不符："+path,422);}catch(com.ruoyi.common.exception.ServiceException e){throw e;}catch(RuntimeException e){throw error("工具Draft7校验失败："+path,422);}}
 static void response(Object value,JSONObject raw,JSONObject api){var schema=FACTORY.getSchema(bundled(raw,api).toJSONString(JSONWriter.Feature.WriteMapNullValue),InputFormat.JSON,SchemaValidatorsConfig.builder().formatAssertionsEnabled(false).build());var errors=schema.validate(JSON.toJSONString(value,JSONWriter.Feature.WriteMapNullValue),InputFormat.JSON);for(var fault:errors){var at=fault.getInstanceLocation();if(!"type".equals(fault.getType())||fault.getInstanceNode()==null||!fault.getInstanceNode().isNull()||at.getNameCount()==0)throw error("工具原响应Schema不符",422);var definition=fault.getSchemaNode();String type=definition==null?null:definition.isTextual()?definition.asText():definition.path("type").asText();Object replacement=switch(type==null?"":type){case "string"->"";case "number","integer"->0;case "object"->new JSONObject();case "array"->new JSONArray();case "boolean"->false;default->throw error("工具原null响应类型无默认值",422);};Object target=value;for(int index=0;index<at.getNameCount()-1;index++){Object key=at.getElement(index);if(target instanceof JSONObject object)target=object.get(key.toString());else if(target instanceof JSONArray array)target=array.get(Integer.parseInt(key.toString()));else throw error("工具原null响应路径无效",422);}String last=at.getElement(at.getNameCount()-1).toString();if(target instanceof JSONObject object)object.put(last,replacement);else if(target instanceof JSONArray array)array.set(Integer.parseInt(last),replacement);else throw error("工具原null响应路径无效",422);}}
}
